import type { CalculatorSeoData } from './types';
import { SRC } from './sources';
// ---------------------------------------------------------------------------
// Inventory Valuation Calculator — FIFO, LIFO and weighted average (Phase 17;
// absorbs the fifo-, lifo- and weighted-average-cost pages). Every figure is
// generated by computeInventoryValuation(), the function the calculator runs.
// ---------------------------------------------------------------------------
import { computeInventoryValuation, INVENTORY_DEFAULTS } from '@/lib/pricing/inventory-valuation';

const usd = (n: number) => n.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
const usd0 = (n: number) => n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const pct = (n: number, d = 1) => `${n.toFixed(d)}%`;

const base = computeInventoryValuation(INVENTORY_DEFAULTS);
const L = INVENTORY_DEFAULTS.layers;
const falling = computeInventoryValuation({ layers: [{ label: 'Beginning inventory', units: 200, unitCost: 48 }, { label: 'Purchase 1', units: 300, unitCost: 42 }, { label: 'Purchase 2', units: 250, unitCost: 39 }], unitsSold: 560, sellingPrice: 79, taxRatePct: 21 });
const twoLayer = computeInventoryValuation({ layers: [{ label: 'Beginning inventory', units: 100, unitCost: 10 }, { label: 'Purchase 1', units: 150, unitCost: 12 }], unitsSold: 200 });
const revenue = base.unitsSold * (INVENTORY_DEFAULTS.sellingPrice ?? 0);

const layerText = (r: typeof base.fifo) =>
  r.layers.filter((l) => l.sold > 0).map((l) => `${Number.isInteger(l.sold) ? l.sold : l.sold.toFixed(1)} × ${usd(r.method === 'average' ? base.weightedAverageCost : l.unitCost)}`).join(' + ');

